-- A64: corrige ambiguidade entre parâmetros de saída e colunas nas leituras minimizadas da Loteadora.
-- Não cria dados, não expõe documentos, financeiro, contratos, valores, percentuais, pagamentos ou repasses.

create or replace function public.subdivision_list_draft_buyer_clients(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(buyer_client_id uuid,party_role_assignment_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select buyer_client.id,buyer_client.party_role_assignment_id,buyer_client.created_at from public.subdivision_buyer_clients buyer_client where buyer_client.organization_id=p_organization_id order by buyer_client.created_at desc;end;$$;

create or replace function public.subdivision_list_buyer_attachment_intents(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(attachment_intent_id uuid,buyer_client_id uuid,created_at timestamptz,attachment_state text) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select intent.id,intent.buyer_client_id,intent.created_at,case when intent.storage_key is null then 'awaiting_private_upload' else 'private_upload_recorded' end from public.subdivision_buyer_attachment_intents intent where intent.organization_id=p_organization_id order by intent.created_at desc;end;$$;

create or replace function public.subdivision_list_sale_drafts(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_draft_id uuid,lot_id uuid,buyer_client_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select sale_draft.id,sale_draft.lot_id,sale_draft.buyer_client_id,sale_draft.created_at from public.subdivision_sale_drafts sale_draft where sale_draft.organization_id=p_organization_id order by sale_draft.created_at desc;end;$$;

