create or replace function public.subdivision_list_sale_draft_co_buyers(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(sale_draft_co_buyer_id uuid,sale_draft_id uuid,buyer_client_id uuid,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select co_buyer.id,co_buyer.sale_draft_id,co_buyer.buyer_client_id,co_buyer.created_at from public.subdivision_sale_draft_co_buyers co_buyer where co_buyer.organization_id=p_organization_id order by co_buyer.created_at desc;end;$$;

create or replace function public.subdivision_list_economic_rule_sets(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(economic_rule_set_id uuid,development_id uuid,version_reference text,working_state text,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select rule_set.id,rule_set.development_id,rule_set.version_reference,rule_set.working_state,rule_set.created_at from public.subdivision_economic_rule_sets rule_set where rule_set.organization_id=p_organization_id order by rule_set.created_at desc;end;$$;

create or replace function public.subdivision_list_economic_rule_components(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(economic_rule_component_id uuid,economic_rule_set_id uuid,component_code text,working_state text,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select component.id,component.economic_rule_set_id,component.component_code,component.working_state,component.created_at from public.subdivision_economic_rule_components component where component.organization_id=p_organization_id order by component.created_at desc;end;$$;

